/* Toast close button sits inside the toast, top right (sonner default: outside corner). */
[data-sonner-toast] [data-close-button] {
  left: auto;
  right: 8px;
  top: 8px;
  transform: none;
  background: transparent;
  border: none;
  color: inherit;
  opacity: 0.7;
}

[data-sonner-toast] [data-close-button]:hover {
  background: rgba(0, 0, 0, 0.08);
  opacity: 1;
}

/* Keep the message text clear of the button. */
[data-sonner-toast] [data-content] {
  padding-right: 20px;
}

/* Toast close button sits inside the toast, top right (sonner default: outside corner).
   Sonner injects its stylesheet at runtime, so these rules need !important. */
[data-sonner-toaster] [data-sonner-toast] [data-close-button] {
  left: auto !important;
  right: 8px !important;
  top: 8px !important;
  transform: none !important;
  width: 20px !important;
  height: 20px !important;
  background: transparent !important;
  border: none !important;
  color: inherit !important;
  opacity: 0.7;
}

[data-sonner-toaster] [data-sonner-toast] [data-close-button]:hover {
  background: rgba(0, 0, 0, 0.08) !important;
  opacity: 1;
}

/* Keep the message text clear of the button. */
[data-sonner-toaster] [data-sonner-toast] [data-content] {
  padding-right: 24px;
}
